<?php
namespace Tests\Feature;
use App\Models\{User,TutorGroup,Apprentice,TrainingSession,AttendanceMark,RegisterFollowupCase as C};
use App\Support\{RegisterActions as R};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class RegisterActionsTest extends TestCase {
 use LazilyRefreshDatabase;
 protected function setUp():void {parent::setUp();$this->travelTo(\Carbon\Carbon::parse('2026-11-15 12:00:00'));}
 private function f():array {$m=User::factory()->create(['role'=>'admin']);$t=User::factory()->create(['role'=>'tutor']);$other=User::factory()->create(['role'=>'tutor']);$g=TutorGroup::factory()->create(['tutor_id'=>$t->id]);$a=Apprentice::factory()->create(['tutor_id'=>$t->id,'tutor_group_id'=>$g->id]);$s=TrainingSession::factory()->create(['tutor_group_id'=>$g->id,'created_by'=>$m->id,'session_date'=>'2026-11-10','members'=>[$a->id]]);return compact('m','t','other','g','a','s');}
 private function data(array $f):array {return ['owner_id'=>$f['t']->id,'due_on'=>today()->addDays(5)->toDateString(),'note'=>'PRIVATE-OPERATIONAL-NOTE'];}
 private function create(array $f,?User $actor=null):C {return R::save($actor??$f['t'],1,$f['s'],null,0,R::check($f['s'])['hash'],$this->data($f));}
 private function invalid(callable $f):void {try{$f();$this->fail('Invalid register action accepted');}catch(ValidationException){$this->assertTrue(true);}}
 public function test_missing_register_flag_creates_scoped_encrypted_followup_and_no_marks():void {$f=$this->f();Notification::fake();$c=$this->create($f);$this->assertTrue(R::intact($c));$this->assertTrue(R::check($f['s'])['flag']);$this->assertSame('Open',R::position($c,$f['s'])['label']);$raw=DB::table('register_followup_cases')->value('details');$this->assertStringNotContainsString('PRIVATE-OPERATIONAL',$raw);$this->assertStringContainsString('PRIVATE-OPERATIONAL',Crypt::decryptString($raw));$this->assertDatabaseCount('attendance_marks',0);Notification::assertNothingSent();}
 public function test_only_current_full_group_main_tutor_or_manager_can_access():void {$f=$this->f();$this->assertTrue(R::allowed($f['t'],$f['s']));$this->assertTrue(R::allowed($f['m'],$f['s']));$this->assertFalse(R::allowed($f['other'],$f['s']));$f['a']->tutor_id=$f['other']->id;$f['a']->save();$this->assertFalse(R::allowed($f['t'],$f['s']->fresh()));$this->assertFalse(R::allowed($f['other'],$f['s']->fresh()));}
 public function test_future_no_flag_and_duplicate_session_case_refuse():void {$f=$this->f();$c=$this->create($f);$this->invalid(fn()=>$this->create($f));$f['s']->session_date='2026-12-01';$f['s']->save();$g=$this->f();$g['s']->session_date='2026-12-01';$g['s']->save();$this->invalid(fn()=>$this->create($g));$this->assertDatabaseCount('register_followup_cases',1);}
 public function test_incomplete_register_cannot_be_manually_resolved():void {$f=$this->f();$c=$this->create($f);$this->invalid(fn()=>R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'resolve','No fake completion'));$this->assertSame('Open',$c->fresh()->state);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_actual_recognised_register_allows_resolution_without_otj_inference():void {$f=$this->f();$c=$this->create($f);AttendanceMark::create(['training_session_id'=>$f['s']->id,'apprentice_id'=>$f['a']->id,'recorded_by'=>$f['t']->id,'code'=>'A','comment'=>'PRIVATE-ATTENDANCE-COMMENT']);R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'resolve','Actual register checked');$this->assertTrue(R::position($c->fresh(),$f['s'])['resolved']);$this->assertFalse(AttendanceMark::firstOrFail()->otj_confirmed);$this->assertNull(AttendanceMark::firstOrFail()->otj_minutes);}
 public function test_cancelled_session_can_close_tracking_but_never_looks_like_recorded_register():void {$f=$this->f();$c=$this->create($f);$f['s']->state='Cancelled';$f['s']->save();R::decide($f['m'],1,$c,1,R::check($f['s'])['hash'],'resolve','Actual cancellation checked');$p=R::position($c->fresh(),$f['s']);$this->assertTrue($p['resolved']);$this->assertSame('Resolved: session cancelled, no register inferred',$p['label']);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_deferral_and_withdrawal_keep_register_flags_and_history():void {$f=$this->f();$c=$this->create($f);R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'defer','Waiting for actual source');$this->assertTrue(R::position($c->fresh(),$f['s'])['deferred']);$this->assertTrue(R::check($f['s'])['flag']);R::decide($f['t'],1,$c->fresh(),2,R::check($f['s'])['hash'],'withdraw','Tracking withdrawn');$this->assertTrue(R::position($c->fresh(),$f['s'])['withdrawn']);$this->assertTrue(R::check($f['s'])['flag']);}
 public function test_source_correction_after_resolution_requires_recheck():void {$f=$this->f();$c=$this->create($f);$mark=AttendanceMark::create(['training_session_id'=>$f['s']->id,'apprentice_id'=>$f['a']->id,'recorded_by'=>$f['t']->id,'code'=>'O']);R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'resolve','Actual register');$mark->code=null;$mark->save();$this->assertFalse(R::position($c->fresh(),$f['s'])['resolved']);$this->assertTrue(R::check($f['s'])['flag']);}
 public function test_stale_hash_or_version_refuses_edits_and_decisions():void {$f=$this->f();$c=$this->create($f);$old=R::check($f['s'])['hash'];$f['s']->version++;$f['s']->save();$this->invalid(fn()=>R::decide($f['t'],1,$c,1,$old,'defer','Stale'));$this->invalid(fn()=>R::save($f['t'],1,$f['s'],$c,2,R::check($f['s'])['hash'],$this->data($f)));$this->assertSame(1,$c->fresh()->version);}
 public function test_wrong_owner_or_inactive_owner_refuses_and_lost_owner_is_labelled():void {$f=$this->f();$d=$this->data($f);$d['owner_id']=$f['other']->id;$this->invalid(fn()=>R::save($f['t'],1,$f['s'],null,0,R::check($f['s'])['hash'],$d));$c=$this->create($f);$f['t']->active=false;$f['t']->save();$this->assertFalse(R::position($c,$f['s'])['owner_current']);$this->assertSame('Owner access needs reassignment',R::position($c,$f['s'])['label']);}
 public function test_old_note_scope_cannot_be_inherited_by_new_tutor_after_roster_replacement():void {$f=$this->f();$c=$this->create($f);$b=Apprentice::factory()->create(['tutor_id'=>$f['other']->id]);$f['g']->tutor_id=$f['other']->id;$f['g']->save();$f['s']->members=[$b->id];$f['s']->save();$s=$f['s']->fresh();$this->assertTrue(R::allowed($f['other'],$s));$this->assertFalse(R::caseAllowed($f['other'],$c,$s));$this->actingAs($f['other'])->get('/sessions/'.$s->id.'/follow-up')->assertForbidden();$this->actingAs($f['m'])->get('/sessions/'.$s->id.'/follow-up')->assertOk();}
 public function test_manager_rebaseline_current_scope_releases_only_new_safe_note():void {$f=$this->f();$c=$this->create($f);$b=Apprentice::factory()->create(['tutor_id'=>$f['other']->id]);$f['g']->tutor_id=$f['other']->id;$f['g']->save();$f['s']->members=[$b->id];$f['s']->save();$d=$this->data($f);$d['owner_id']=$f['other']->id;$d['note']='NEW-SAFE-OPERATIONAL-NOTE';$c=R::save($f['m'],1,$f['s']->fresh(),$c,1,R::check($f['s'])['hash'],$d);$this->assertTrue(R::caseAllowed($f['other'],$c,$f['s']->fresh()));$this->actingAs($f['other'])->get('/sessions/'.$f['s']->id.'/follow-up')->assertOk()->assertSee('NEW-SAFE-OPERATIONAL-NOTE')->assertDontSee('PRIVATE-OPERATIONAL-NOTE');}
 public function test_raw_metadata_or_plaintext_resolved_state_does_not_look_current():void {$f=$this->f();$c=$this->create($f);DB::table('register_followup_cases')->where('id',$c->id)->update(['state'=>'Resolved']);$this->assertFalse(R::position($c->fresh(),$f['s'])['resolved']);DB::table('register_followup_cases')->where('id',$c->id)->update(['owner_id'=>$f['other']->id]);$this->assertFalse(R::intact($c->fresh()));}
 public function test_required_save_and_decision_audit_failures_roll_back():void {$f=$this->f();$c=$this->create($f);AuditFault::install('reg_action_fault','register_followup_events','Synthetic failure','case_defer');try{R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'defer','Synthetic');$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Open',$c->fresh()->state);$this->assertNull($c->fresh()->proof);}
 public function test_required_creation_audit_failure_rolls_back_case():void {$f=$this->f();AuditFault::install('reg_action_create_fault','register_followup_events','Synthetic failure');try{$this->create($f);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('register_followup_cases',0);}
 public function test_overdue_deferral_needs_new_date_and_edit_reopens_proof():void {$f=$this->f();$c=$this->create($f);$this->travel(6)->days();$this->assertTrue(R::position($c,$f['s'])['overdue']);$this->invalid(fn()=>R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'defer','Overdue'));$c=R::save($f['t'],1,$f['s'],$c,1,R::check($f['s'])['hash'],$this->data($f));$this->assertSame('Open',$c->state);$this->assertFalse(R::position($c,$f['s'])['overdue']);}
 public function test_service_rechecks_actor_auth_and_current_session_scope():void {$f=$this->f();$c=$this->create($f);$f['t']->auth_version=2;$f['t']->save();try{R::decide($f['t'],1,$c,1,R::check($f['s'])['hash'],'defer','Stale actor');$this->fail('Stale actor accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_scope_filtered_queue_and_followup_form_do_not_expose_other_case_notes():void {$f=$this->f();$c=$this->create($f);$other=$this->f();$other['s']->name='PRIVATE-OTHER-SESSION';$other['s']->save();$this->create($other);$this->actingAs($f['t'])->get('/session-operations/register-actions')->assertOk()->assertDontSee('PRIVATE-OTHER-SESSION')->assertDontSee('PRIVATE-OPERATIONAL');$this->get('/sessions/'.$f['s']->id.'/follow-up')->assertOk()->assertSee('PRIVATE-OPERATIONAL-NOTE')->assertHeader('Referrer-Policy','no-referrer');}
 public function test_ordinary_non_tutor_roles_cannot_read_or_write_cases():void {$f=$this->f();$this->create($f);foreach(['mentor','careers_adviser','apprentice','employer','staff','inclusion_lead']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/session-operations/register-actions')->assertForbidden();$this->get('/sessions/'.$f['s']->id.'/follow-up')->assertForbidden();$this->post('/sessions/'.$f['s']->id.'/follow-up',[])->assertForbidden();}}
 public function test_form_validation_and_read_only_gets_create_no_marks():void {$f=$this->f();$this->actingAs($f['t'])->get('/sessions/'.$f['s']->id.'/follow-up')->assertOk();$this->post('/sessions/'.$f['s']->id.'/follow-up',[])->assertSessionHasErrors(['source_hash','owner_id','due_on','note','confirmed']);$this->assertDatabaseCount('register_followup_cases',0);$this->assertDatabaseCount('attendance_marks',0);}
}
